@import "tailwindcss";

:root {
  --bg: #05060f;
  --sidebar-bg: rgba(7, 9, 20, 0.98);
  --card: rgba(18, 20, 34, 0.78);
  --border: rgba(255, 255, 255, 0.09);
  --border-strong: rgba(255, 255, 255, 0.15);

  --text: #f7f8fc;
  --muted: #a2a8b7;
  --muted-soft: #747b8c;

  --cyan: #22d3ee;
  --blue: #3b82f6;
  --purple: #8b5cf6;
  --rose: #fb7185;
  --amber: #fbbf24;
  --emerald: #34d399;

  --sidebar-width: 292px;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  min-height: 100%;
  margin: 0;
  overflow-x: hidden;
  background:
    radial-gradient(circle at 78% 0%, rgba(79, 70, 229, 0.15), transparent 34%),
    radial-gradient(circle at 10% 18%, rgba(34, 211, 238, 0.07), transparent 28%),
    var(--bg);
  color: var(--text);
  font-family:
    "Manrope",
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Arial,
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  line-height: 1.45;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  border: 0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

*::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

*::-webkit-scrollbar-track {
  background: transparent;
}

*::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.14);
  border-radius: 999px;
}

*::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.24);
}

/* Layout */
.app-shell {
  width: 100%;
  min-height: 100vh;
  overflow-x: hidden;
}

.sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: var(--sidebar-width);
  height: 100vh;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 34px 22px 28px;
  background:
    linear-gradient(180deg, rgba(8, 10, 22, 0.98), rgba(5, 7, 16, 0.99)),
    var(--sidebar-bg);
  border-right: 1px solid var(--border);
  z-index: 50;
}

.content {
  width: calc(100vw - var(--sidebar-width));
  max-width: calc(100vw - var(--sidebar-width));
  margin-left: var(--sidebar-width);
  min-height: 100vh;
  padding: 40px 46px 64px;
  overflow-x: hidden;
}

/* Sidebar */
.brand {
  margin-bottom: 34px;
  font-size: 31px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: 5px;
  background: linear-gradient(90deg, #818cf8, #22d3ee);
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.brand::after {
  content: "";
  display: block;
  width: 100%;
  height: 1px;
  margin-top: 28px;
  background: linear-gradient(90deg, rgba(34, 211, 238, 0.18), transparent);
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.side-group {
  width: 100%;
}

.side-group-trigger {
  width: 100%;
  min-height: 52px;
  padding: 0 14px;
  border-radius: 18px;
  border: 1px solid transparent;
  background: transparent;
  color: #9aa3b8;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  cursor: pointer;
  outline: none;
  box-shadow: none;
  transition:
    background 0.22s ease,
    border-color 0.22s ease,
    color 0.22s ease;
}

.side-group-trigger:hover {
  color: #f8fafc;
  background: rgba(255, 255, 255, 0.045);
}

.side-group.is-open .side-group-trigger {
  color: #f8fafc;
  background: linear-gradient(
    135deg,
    rgba(34, 211, 238, 0.105),
    rgba(129, 140, 248, 0.055)
  );
  border-color: rgba(34, 211, 238, 0.18);
}

.side-title {
  display: flex;
  align-items: center;
  gap: 11px;
  font-size: 15px;
  line-height: 1;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.side-dot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.45);
  transition:
    background 0.22s ease,
    box-shadow 0.22s ease;
}

.side-group.is-open .side-dot {
  background: var(--cyan);
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.8);
}

.side-arrow {
  width: 28px;
  height: 28px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  color: #94a3b8;
  background: rgba(255, 255, 255, 0.045);
  transition:
    transform 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    color 0.22s ease,
    background 0.22s ease;
}

.side-group-trigger:hover .side-arrow {
  color: #fff;
  background: rgba(255, 255, 255, 0.075);
}

.side-group.is-open .side-arrow {
  transform: rotate(180deg);
  color: var(--cyan);
  background: rgba(34, 211, 238, 0.1);
}

/* Smooth dropdown */
.side-submenu {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transform: translateY(-6px);
  transition:
    grid-template-rows 0.34s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.22s ease,
    transform 0.34s cubic-bezier(0.22, 1, 0.36, 1);
}

.side-group.is-open .side-submenu {
  grid-template-rows: 1fr;
  opacity: 1;
  transform: translateY(0);
}

.side-submenu-inner {
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-left: 19px;
  padding-left: 17px;
  border-left: 1px solid rgba(255, 255, 255, 0.08);
}

.side-group.is-open .side-submenu-inner {
  padding-top: 10px;
  padding-bottom: 14px;
}

.side-subitem {
  width: 100%;
  padding: 11px 15px;
  border-radius: 14px;
  background: transparent;
  color: #a6aebe;
  text-align: left;
  cursor: pointer;
  font-size: 14px;
  line-height: 1.2;
  font-weight: 500;
  letter-spacing: -0.02em;
  outline: none;
  transition:
    background 0.18s ease,
    color 0.18s ease,
    transform 0.18s ease;
}

.side-subitem:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.055);
  transform: translateX(2px);
}

.side-subitem.is-active {
  position: relative;
  color: var(--cyan);
  background: rgba(34, 211, 238, 0.13);
}

.side-subitem.is-active::before {
  content: "";
  position: absolute;
  left: -18px;
  top: 50%;
  width: 2px;
  height: 22px;
  transform: translateY(-50%);
  border-radius: 999px;
  background: var(--cyan);
  box-shadow: 0 0 12px rgba(34, 211, 238, 0.75);
}

/* Header */
.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 28px;
  margin-bottom: 32px;
}

.title-row {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

h1 {
  margin: 0;
  font-size: clamp(42px, 4vw, 58px);
  line-height: 0.95;
  font-weight: 600;
  letter-spacing: -0.065em;
}

.dashboard-header p {
  margin: 12px 0 0;
  color: var(--cyan);
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.01em;
}

.status-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 13px;
  border-radius: 999px;
  border: 1px solid rgba(129, 140, 248, 0.34);
  background: rgba(99, 102, 241, 0.12);
  color: #c7d2fe;
  font-size: 12px;
  font-weight: 600;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: #818cf8;
  box-shadow: 0 0 14px rgba(129, 140, 248, 0.9);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.primary-btn,
.secondary-btn,
.row-action {
  border-radius: 999px;
  cursor: pointer;
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.01em;
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.primary-btn {
  padding: 13px 26px;
  background: linear-gradient(135deg, #a855f7, #2563eb);
  box-shadow: 0 14px 34px rgba(99, 102, 241, 0.26);
}

.secondary-btn {
  padding: 13px 24px;
  border: 1px solid var(--border-strong);
  background: rgba(255, 255, 255, 0.055);
}

.primary-btn:hover,
.secondary-btn:hover,
.row-action:hover {
  transform: translateY(-1px);
  border-color: rgba(255, 255, 255, 0.25);
}

/* Cards */
.glass-card {
  border: 1px solid var(--border);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.036), rgba(255, 255, 255, 0.014)),
    var(--card);
  border-radius: 24px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035), 0 22px 62px rgba(0, 0, 0, 0.25);
  backdrop-filter: blur(18px);
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 22px;
  margin-bottom: 28px;
}

.kpi-card {
  min-height: 166px;
  padding: 24px;
  position: relative;
  overflow: hidden;
}

.kpi-card::before {
  content: "";
  position: absolute;
  right: -60px;
  bottom: -70px;
  width: 180px;
  height: 180px;
  border-radius: 999px;
  filter: blur(26px);
  opacity: 0.15;
}

.kpi-card.cyan::before { background: var(--cyan); }
.kpi-card.rose::before { background: var(--rose); }
.kpi-card.amber::before { background: var(--amber); }
.kpi-card.emerald::before { background: var(--emerald); }

.kpi-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
  color: #a8afbf;
  font-size: 13px;
  line-height: 1.3;
  font-weight: 600;
}

.tiny-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  margin-top: 5px;
  border-radius: 999px;
}

.tiny-dot.cyan { background: var(--cyan); box-shadow: 0 0 15px rgba(34, 211, 238, 0.75); }
.tiny-dot.rose { background: var(--rose); box-shadow: 0 0 15px rgba(251, 113, 133, 0.75); }
.tiny-dot.amber { background: var(--amber); box-shadow: 0 0 15px rgba(251, 191, 36, 0.75); }
.tiny-dot.emerald { background: var(--emerald); box-shadow: 0 0 15px rgba(52, 211, 153, 0.75); }
.tiny-dot.indigo { background: #818cf8; box-shadow: 0 0 15px rgba(129, 140, 248, 0.75); }

.kpi-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 14px;
}

.kpi-main strong {
  font-size: clamp(42px, 3.5vw, 54px);
  line-height: 0.95;
  font-weight: 400;
  letter-spacing: -0.055em;
}

.mini-trend {
  width: 76px;
  height: 32px;
  opacity: 0.82;
  flex: 0 0 auto;
}

.mini-trend-cyan { color: var(--cyan); }
.mini-trend-rose { color: var(--rose); }
.mini-trend-amber { color: var(--amber); }
.mini-trend-emerald { color: var(--emerald); }

.kpi-caption {
  margin: 0;
  width: fit-content;
  max-width: 100%;
  padding: 7px 11px;
  border-radius: 999px;
  font-size: 12px;
  line-height: 1.15;
  font-weight: 500;
  white-space: nowrap;
}

.kpi-caption.cyan {
  color: var(--cyan);
  border: 1px solid rgba(34, 211, 238, 0.26);
  background: rgba(34, 211, 238, 0.09);
}

.kpi-caption.rose {
  color: var(--rose);
  border: 1px solid rgba(251, 113, 133, 0.3);
  background: rgba(251, 113, 133, 0.11);
}

.kpi-caption.amber {
  color: var(--amber);
  border: 1px solid rgba(251, 191, 36, 0.3);
  background: rgba(251, 191, 36, 0.11);
}

.kpi-caption.emerald {
  color: var(--emerald);
  border: 1px solid rgba(52, 211, 153, 0.26);
  background: rgba(52, 211, 153, 0.09);
}

/* Panels */
.two-column-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 28px;
  margin-bottom: 28px;
}

.panel-card {
  padding: 28px;
}

.panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 18px;
  margin-bottom: 20px;
  border-bottom: 1px solid var(--border);
}

.panel-header.stacked {
  display: block;
}

.panel-header h2 {
  margin: 0;
  font-size: clamp(24px, 2vw, 30px);
  line-height: 1.14;
  font-weight: 600;
  letter-spacing: -0.055em;
}

.panel-header p {
  margin: 7px 0 0;
  color: #8f96a7;
  font-size: 13px;
  font-weight: 500;
}

.pill,
.badge,
.mini-status {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border-radius: 999px;
  border: 1px solid;
  line-height: 1.15;
  font-size: 12px;
  font-weight: 500;
}

.pill { padding: 7px 12px; }
.badge { padding: 5px 9px; }
.mini-status { padding: 6px 9px; font-style: normal; }

.pill.cyan,
.badge.cyan,
.mini-status.cyan {
  color: var(--cyan);
  border-color: rgba(34, 211, 238, 0.26);
  background: rgba(34, 211, 238, 0.09);
}

.pill.rose,
.badge.rose,
.mini-status.rose {
  color: var(--rose);
  border-color: rgba(251, 113, 133, 0.3);
  background: rgba(251, 113, 133, 0.11);
}

.badge.amber,
.mini-status.amber {
  color: var(--amber);
  border-color: rgba(251, 191, 36, 0.3);
  background: rgba(251, 191, 36, 0.11);
}

.mini-status.emerald {
  color: var(--emerald);
  border-color: rgba(52, 211, 153, 0.26);
  background: rgba(52, 211, 153, 0.09);
}

.badge.gray,
.mini-status.gray {
  color: #cbd5e1;
  border-color: rgba(148, 163, 184, 0.24);
  background: rgba(148, 163, 184, 0.09);
}

.mini-status.indigo {
  color: #a5b4fc;
  border-color: rgba(129, 140, 248, 0.3);
  background: rgba(129, 140, 248, 0.11);
}

.item-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.legacy-recovery-row {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  padding: 16px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  background: rgba(255, 255, 255, 0.028);
}

.row-left {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 14px;
}

.avatar {
  width: 46px;
  height: 46px;
  min-width: 46px;
  flex: 0 0 46px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid rgba(34, 211, 238, 0.42);
  background: rgba(255, 255, 255, 0.08);
  box-shadow: 0 0 20px rgba(34, 211, 238, 0.16);
}

.avatar img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.avatar span {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #22d3ee, #8b5cf6);
  color: #fff;
  font-size: 13px;
  font-weight: 600;
}

.row-text {
  min-width: 0;
}

.legacy-recovery-row h3 {
  margin: 0;
  font-size: 16px;
  line-height: 1.22;
  font-weight: 600;
  letter-spacing: -0.025em;
}

.legacy-recovery-row p,
.legacy-recovery-row small,
.row-meta span:last-child {
  color: #98a0b2;
  font-size: 13px;
  line-height: 1.45;
}

.legacy-recovery-row p {
  margin: 4px 0 0;
}

.legacy-recovery-row small {
  display: block;
  margin-top: 4px;
}

.row-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-top: 7px;
}

.row-action {
  padding: 10px 16px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.065);
  white-space: nowrap;
}

/* Source */
.source-layout {
  display: grid;
  grid-template-columns: 138px minmax(0, 1fr);
  gap: 26px;
  align-items: center;
}

.donut-chart {
  width: 126px;
  height: 126px;
  border-radius: 999px;
  background:
    radial-gradient(circle at center, #080914 56%, transparent 57%),
    conic-gradient(
      from 90deg,
      #a855f7 0 42%,
      #22d3ee 42% 77%,
      #34d399 77% 89%,
      #94a3b8 89% 97%,
      #374151 97% 100%
    );
  display: grid;
  place-items: center;
  position: relative;
}

.donut-chart span {
  font-size: 27px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: -0.035em;
}

.donut-chart small {
  position: absolute;
  top: 77px;
  color: #8d94a8;
  font-size: 10px;
  font-weight: 500;
}

.source-list {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.source-row > div:first-child {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 7px;
  color: #a8adbd;
  font-size: 13px;
  font-weight: 500;
}

.progress-track {
  width: 100%;
  height: 6px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.075);
}

.progress-fill {
  height: 100%;
  border-radius: 999px;
}

.source-purple { background: linear-gradient(90deg, #d946ef, #8b5cf6); }
.source-cyan { background: linear-gradient(90deg, #3b82f6, #22d3ee); }
.source-green { background: linear-gradient(90deg, #10b981, #34d399); }
.source-gray { background: #94a3b8; }
.source-muted { background: #64748b; }

/* Automation */
.automation-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.mini-stat {
  min-height: 126px;
  padding: 20px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  background: rgba(255, 255, 255, 0.025);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.mini-stat.ghost {
  border-style: dashed;
  opacity: 0.72;
}

.mini-stat strong {
  font-size: 32px;
  line-height: 1;
  font-weight: 400;
  letter-spacing: -0.045em;
}

.mini-stat span {
  margin: 9px 0 13px;
  color: #a1a7b8;
  font-size: 13px;
  font-weight: 500;
}

/* Recent Activity Timeline */
.timeline-card {
  position: relative;
  padding: 32px;
  border-radius: 30px;
  overflow: hidden;
}

.activity-timeline {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 30px;
  padding: 8px 0;
}

.activity-timeline::before {
  content: "";
  position: absolute;
  top: 8px;
  bottom: 8px;
  left: 50%;
  transform: translateX(-50%);
  width: 3px;
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    rgba(129, 140, 248, 0.55),
    rgba(59, 130, 246, 0.35),
    rgba(34, 211, 238, 0.35),
    rgba(52, 211, 153, 0.35)
  );
  box-shadow: 0 0 22px rgba(59, 130, 246, 0.16);
}

.timeline-row {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 80px 1fr;
  align-items: center;
  min-height: 130px;
}

.timeline-side {
  display: flex;
  align-items: center;
}

.left-side {
  justify-content: flex-end;
  padding-right: 26px;
}

.right-side {
  justify-content: flex-start;
  padding-left: 26px;
}

.timeline-center {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}

.timeline-row:hover .timeline-center::before {
  content: "";
  position: absolute;
  width: 54px;
  height: 54px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.22), transparent 70%);
  filter: blur(4px);
}

.timeline-node {
  position: relative;
  width: 20px;
  height: 20px;
  border-radius: 999px;
  border: 3px solid #0b0f1b;
  z-index: 2;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.timeline-row:hover .timeline-node {
  transform: scale(1.12);
}

.timeline-node.indigo {
  background: #818cf8;
  box-shadow: 0 0 0 4px rgba(129, 140, 248, 0.08), 0 0 18px rgba(129, 140, 248, 0.7);
}

.timeline-node.amber {
  background: #fbbf24;
  box-shadow: 0 0 0 4px rgba(251, 191, 36, 0.08), 0 0 18px rgba(251, 191, 36, 0.65);
}

.timeline-node.cyan {
  background: #22d3ee;
  box-shadow: 0 0 0 4px rgba(34, 211, 238, 0.08), 0 0 18px rgba(34, 211, 238, 0.7);
}

.timeline-node.emerald {
  background: #34d399;
  box-shadow: 0 0 0 4px rgba(52, 211, 153, 0.08), 0 0 18px rgba(52, 211, 153, 0.65);
}

.timeline-event-card {
  position: relative;
  width: min(100%, 470px);
  padding: 22px 24px;
  border-radius: 24px;
  overflow: hidden;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.032), rgba(255, 255, 255, 0.012)),
    rgba(17, 20, 34, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.075);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.24);
  backdrop-filter: blur(16px);
  transition:
    transform 0.28s ease,
    border-color 0.28s ease,
    box-shadow 0.28s ease,
    background 0.28s ease;
}

.timeline-event-card:hover {
  transform: translateY(-6px) scale(1.01);
  border-color: rgba(129, 140, 248, 0.18);
  box-shadow:
    0 20px 44px rgba(0, 0, 0, 0.34),
    0 0 28px rgba(59, 130, 246, 0.08);
