  font-size: 14px;
  line-height: 1;
  font-weight: 500;
}

.timeline-time.indigo { color: #9aa4ff; }
.timeline-time.amber { color: #fbbf24; }
.timeline-time.cyan { color: #34d9ff; }
.timeline-time.emerald { color: #34d399; }

.indigo-glow { box-shadow: 0 12px 30px rgba(0, 0, 0, 0.24), -8px 0 28px rgba(129, 140, 248, 0.07); }
.amber-glow { box-shadow: 0 12px 30px rgba(0, 0, 0, 0.24), -8px 0 28px rgba(251, 191, 36, 0.07); }
.cyan-glow { box-shadow: 0 12px 30px rgba(0, 0, 0, 0.24), -8px 0 28px rgba(34, 211, 238, 0.07); }
.emerald-glow { box-shadow: 0 12px 30px rgba(0, 0, 0, 0.24), -8px 0 28px rgba(52, 211, 153, 0.07); }

/* Responsive */
@media (max-width: 1240px) {
  .kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .two-column-grid {
    grid-template-columns: 1fr;
  }

  .source-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 900px) {
  :root {
    --sidebar-width: 0px;
  }

  .sidebar {
    position: relative;
    width: 100%;
    height: auto;
    padding: 28px 18px;
    border-right: none;
    border-bottom: 1px solid var(--border);
  }

  .content {
    width: 100%;
    max-width: 100%;
    margin-left: 0;
    padding: 28px 18px 48px;
  }

  .dashboard-header {
    flex-direction: column;
  }

  .header-actions {
    width: 100%;
    justify-content: stretch;
  }

  .primary-btn,
  .secondary-btn {
    flex: 1;
  }

  .activity-timeline::before {
    left: 18px;
    transform: none;
  }

  .timeline-row {
    grid-template-columns: 36px 1fr;
    min-height: auto;
  }

  .timeline-center {
    justify-content: flex-start;
    align-items: flex-start;
    padding-top: 18px;
  }

  .timeline-side {
    grid-column: 2;
    padding: 0;
    justify-content: flex-start;
  }

  .timeline-event-card {
    width: 100%;
  }
}

@media (max-width: 640px) {
  .kpi-grid,
  .automation-grid {
    grid-template-columns: 1fr;
  }

  .panel-card,
  .timeline-card {
    padding: 22px;
  }

  .legacy-recovery-row {
    grid-template-columns: 1fr;
  }

  .row-action {
    width: 100%;
  }
}

