  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 18px;
  margin-bottom: 22px;
  border-bottom: 1px solid var(--border);
}

.recent-card-header h2 {
  margin: 0;
  font-size: 28px;
  line-height: 1.14;
  font-weight: 600;
  letter-spacing: -0.05em;
}

.recent-card-header p {
  margin: 7px 0 0;
  color: #8f96a7;
  font-size: 13px;
  line-height: 1.5;
}

.recent-card-header > span {
  padding: 7px 12px;
  border-radius: 999px;
  color: var(--cyan);
  border: 1px solid rgba(34, 211, 238, 0.24);
  background: rgba(34, 211, 238, 0.09);
  font-size: 12px;
}

.recent-feed {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.recent-feed::before {
  content: "";
  position: absolute;
  top: 12px;
  bottom: 12px;
  left: 10px;
  width: 2px;
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    rgba(129, 140, 248, 0.55),
    rgba(34, 211, 238, 0.3),
    rgba(52, 211, 153, 0.24)
  );
}

.recent-event {
  position: relative;
  width: 100%;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 16px;
  padding: 16px;
  border-radius: 22px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  background: rgba(255, 255, 255, 0.025);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease;
}

.recent-event:hover {
  transform: translateY(-2px);
  border-color: rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.04);
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.22);
}

.recent-event.selected {
  border-color: rgba(34, 211, 238, 0.24);
  background: rgba(34, 211, 238, 0.07);
}

.recent-event-node {
  position: relative;
  z-index: 2;
  width: 14px;
  height: 14px;
  margin-top: 22px;
  border-radius: 999px;
  border: 3px solid #0b0f1b;
}

.recent-event-node.cyan {
  background: var(--cyan);
  box-shadow: 0 0 18px rgba(34, 211, 238, 0.65);
}

.recent-event-node.rose {
  background: var(--rose);
  box-shadow: 0 0 18px rgba(251, 113, 133, 0.65);
}

.recent-event-node.amber {
  background: var(--amber);
  box-shadow: 0 0 18px rgba(251, 191, 36, 0.65);
}

.recent-event-node.emerald {
  background: var(--emerald);
  box-shadow: 0 0 18px rgba(52, 211, 153, 0.65);
}

.recent-event-node.indigo {
  background: #818cf8;
  box-shadow: 0 0 18px rgba(129, 140, 248, 0.65);
}

.recent-event-node.gray {
  background: #94a3b8;
  box-shadow: 0 0 18px rgba(148, 163, 184, 0.45);
}

.recent-event-main {
  min-width: 0;
}

.recent-event-top {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
}

.recent-event-person {
  display: flex;
  gap: 14px;
  min-width: 0;
}

.recent-event h3 {
  margin: 0;
