  border-color: rgba(34, 211, 238, 0.2);
}

@media (max-width: 1240px) {
  .recent-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .recent-workspace {
    grid-template-columns: 1fr;
  }

  .recent-detail-card {
    position: relative;
    top: auto;
  }
}

@media (max-width: 640px) {
  .recent-summary-grid {
    grid-template-columns: 1fr;
  }

  .recent-event-top {
    flex-direction: column;
  }

  .recent-detail-grid {
    grid-template-columns: 1fr;
  }
}

