.capture-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 16px;
}

.capture-actions .primary-btn,
.capture-actions .secondary-btn {
  padding: 11px 15px;
}

.capture-page-notice {
  margin: 16px 0 0;
}

.product-card {
  width: 100%;
  color: inherit;
  text-align: left;
}

.product-card.selected {
  border-color: rgba(34, 211, 238, 0.25);
  background: rgba(34, 211, 238, 0.07);
}

.product-tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.product-tag-list span {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 6px 9px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.045);
  color: #d7dce8;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 600;
}

.detail-tag-list {
  margin: 16px 0 0;
}

.sheet-actions {
  margin-top: 0;
  justify-content: flex-end;
}

.sku-sheet-wrap {
  overflow-x: auto;
  margin: -4px;
  padding: 4px;
}

.sku-sheet {
  min-width: 1880px;
  display: grid;
  gap: 8px;
}

.sku-sheet-row {
  display: grid;
  grid-template-columns:
    140px 220px 150px 88px 130px 160px 105px 150px
    160px 120px 170px 260px 120px 130px 140px 150px;
  align-items: center;
  gap: 8px;
  padding: 10px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  background: rgba(255, 255, 255, 0.026);
}

.sku-sheet-head {
  position: sticky;
  top: 0;
  z-index: 1;
  border-color: rgba(255, 255, 255, 0.12);
  background: rgba(18, 20, 34, 0.96);
}

.sku-sheet-head span {
  color: #a8afbf;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.sku-sheet-row > span,
.sku-sheet-row label {
  min-width: 0;
  color: #d7dce8;
  font-size: 12px;
  line-height: 1.35;
}

.sku-sheet-row input,
.sku-sheet-row select {
  width: 100%;
  min-width: 0;
  padding: 9px 10px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  outline: none;
  background: rgba(255, 255, 255, 0.045);
  color: #f8fafc;
  font-size: 12px;
}

.sku-sheet-row select {
  color-scheme: dark;
}

.sku-sheet-row input:focus,
.sku-sheet-row select:focus {
  border-color: rgba(34, 211, 238, 0.4);
  box-shadow: 0 0 0 3px rgba(34, 211, 238, 0.09);
}

.sku-readonly {
  color: #f8fafc;
  font-weight: 700;
}

.sku-row-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.sku-row-actions button {
  padding: 7px 9px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.055);
  color: #d7dce8;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.sheet-field-summary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 18px;
}

.sheet-field-summary div,
.import-step-grid div {
  padding: 14px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  background: rgba(255, 255, 255, 0.026);
}

.sheet-field-summary span,
.import-step-grid span {
  display: block;
  margin-bottom: 6px;
  color: #7f8799;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.sheet-field-summary p,
.import-step-grid strong {
  margin: 0;
  color: #d7dce8;
  font-size: 13px;
  line-height: 1.5;
  font-weight: 600;
}

.product-taxonomy-grid {
  align-items: start;
}

.tag-suggestion-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 0.34fr);
  gap: 18px;
  align-items: start;
}

.product-tag-bank {
  position: sticky;
  top: 18px;
}

.import-export-grid {
  align-items: start;
}

.import-step-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.import-preview-list,
.export-option-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 18px;
}

.import-preview-row,
.export-option-card {
  position: relative;
  overflow: hidden;
  padding: 16px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  background: rgba(255, 255, 255, 0.026);
}

.export-option-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
}

.export-option-card .secondary-btn {
  padding: 10px 15px;
}

.import-preview-row h3,
.export-option-card h3 {
  margin: 0;
  color: #f8fafc;
  font-size: 15px;
  line-height: 1.25;
  font-weight: 700;
}

.import-preview-row p,
.export-option-card p {
  margin: 6px 0 0;
  color: #98a0b2;
  font-size: 13px;
  line-height: 1.5;
}

.buyer-kpi-grid {
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.buyer-workspace {
  align-items: start;
}

.buyer-card {
  width: 100%;
  color: inherit;
  text-align: left;
}

.buyer-card.selected {
  border-color: rgba(34, 211, 238, 0.25);
  background: rgba(34, 211, 238, 0.07);
}

.buyer-card-main {
  align-items: center;
}

.buyer-identity {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 14px;
}

.buyer-stat-grid {
  grid-template-columns: 112px 130px minmax(160px, 0.7fr) minmax(260px, 1fr);
}

.buyer-detail-stack {
  display: grid;
  gap: 14px;
}

.buyer-detail-stack > div + div {
  padding-top: 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.065);
}

.buyer-detail-stack span {
  display: block;
  margin-bottom: 6px;
  color: #7f8799;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.buyer-detail-stack p {
  margin: 0;
  color: #d7dce8;
  font-size: 13px;
  line-height: 1.55;
}

.source-stat-grid {
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
}

.revenue-kpi-grid {
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.revenue-stage-list {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.revenue-stage-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.stage-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 0 2px;
}

.stage-heading h3 {
  margin: 0;
  color: #f8fafc;
  font-size: 14px;
  line-height: 1.2;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.stage-heading span {
  color: #a8afbf;
  font-size: 12px;
}

.pipeline-card {
  width: 100%;
  color: inherit;
  text-align: left;
}

.pipeline-card.selected {
  border-color: rgba(34, 211, 238, 0.25);
  background: rgba(34, 211, 238, 0.07);
}

.summary-breakdown-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.summary-breakdown-card {
  padding: 18px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.036), rgba(255, 255, 255, 0.014)),
    rgba(18, 20, 34, 0.78);
}

.summary-breakdown-card h3 {
  margin: 0 0 14px;
  color: #f8fafc;
  font-size: 16px;
  line-height: 1.25;
  font-weight: 600;
  letter-spacing: -0.025em;
}

.summary-breakdown-card div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.065);
}

.summary-breakdown-card span {
  color: #a8afbf;
  font-size: 12px;
  line-height: 1.35;
}

.summary-breakdown-card strong {
  color: #f8fafc;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

.placeholder-panel {
  max-width: 980px;
}

@media (max-width: 1340px) {
  .recovery-kpi-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .activity-summary-strip {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .recovery-workspace,
  .inquiry-card,
  .capture-workspace {
    grid-template-columns: 1fr;
  }

  .tag-suggestion-layout {
    grid-template-columns: 1fr;
  }

  .product-tag-bank {
    position: relative;
    top: auto;
  }

  .recovery-detail-panel {
    position: relative;
    top: auto;
  }

  .task-money,
  .inquiry-value,
  .capture-value-stack {
    align-items: flex-start;
    text-align: left;
  }
}

@media (max-width: 1080px) {
  .recovery-kpi-grid,
  .recovery-overview-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .activity-summary-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .summary-breakdown-grid {
    grid-template-columns: 1fr;
  }

  .product-taxonomy-grid,
  .import-export-grid,
  .sheet-field-summary,
  .import-step-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .recovery-kpi-grid,
  .recovery-overview-grid,
  .activity-summary-strip,
  .detail-grid,
  .export-option-card {
    grid-template-columns: 1fr;
  }

  .recovery-row,
  .recovery-task-card,
  .team-load-card,
  .detail-heading,
  .activity-row-top,
  .capture-card-main,
  .buyer-identity,
  .capture-stat-grid {
    grid-template-columns: 1fr;
    align-items: flex-start;
  }

  .recovery-row,
  .recovery-task-card,
  .team-load-card,
  .detail-heading,
  .activity-row-top,
  .export-option-card,
  .template-box > div,
  .thread-header {
    flex-direction: column;
  }

  .recovery-row > strong,
  .detail-heading > strong {
    margin-left: 60px;
  }

  .thread-header span {
    text-align: left;
  }
}

/* Altynx light enterprise redesign */
:root {
  color-scheme: light;
  --altynx-orange: #ff4500;
  --altynx-orange-light: #ff6b35;
  --altynx-orange-dark: #cc3700;
  --altynx-black: #000000;
  --altynx-dark: #0c0c0c;
  --altynx-surface-dark: #141414;
  --altynx-border-dark: #2a2a2a;
  --altynx-gray: #909090;
  --altynx-white: #ffffff;

  --bg: #f7f7f8;
  --sidebar-bg: #ffffff;
  --card: #ffffff;
  --card-soft: #fbfbfc;
  --surface-raised: #ffffff;
  --surface-subtle: #f4f4f5;
  --border: rgba(42, 42, 42, 0.1);
  --border-strong: rgba(42, 42, 42, 0.16);
  --text: #111111;
  --muted: #6b7280;
  --muted-soft: #909090;
  --accent: var(--altynx-orange);
  --accent-hover: var(--altynx-orange-light);
  --accent-strong: var(--altynx-orange-dark);
  --accent-soft: rgba(255, 69, 0, 0.08);
  --accent-border: rgba(255, 69, 0, 0.18);
  --shadow-soft: 0 1px 2px rgba(12, 12, 12, 0.04), 0 12px 34px rgba(12, 12, 12, 0.06);
  --shadow-tiny: 0 1px 2px rgba(12, 12, 12, 0.04);
  --radius-xs: 6px;
  --radius-sm: 8px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --sidebar-width: 284px;

  --cyan: #2563eb;
  --blue: #2563eb;
  --purple: #6d5bd0;
  --rose: #dc2626;
  --amber: #d97706;
  --emerald: #059669;
}

html,
body {
  background: var(--bg) !important;
  color: var(--text) !important;
  font-family:
    "Inter",
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Arial,
    sans-serif !important;
}

body {
  line-height: 1.45;
}

*::selection {
  background: rgba(255, 69, 0, 0.18);
  color: var(--text);
}

*::-webkit-scrollbar-thumb {
  background: rgba(42, 42, 42, 0.18);
}

*::-webkit-scrollbar-thumb:hover {
  background: rgba(42, 42, 42, 0.28);
}

.app-shell {
  background:
    linear-gradient(180deg, #fbfbfc 0, var(--bg) 280px),
    var(--bg);
}

.sidebar {
  padding: 22px 16px 24px;
  background: var(--sidebar-bg) !important;
  border-right: 1px solid var(--border);
  box-shadow: 1px 0 0 rgba(255, 255, 255, 0.85);
  color: #374151;
}

.content {
  padding: 28px 32px 48px;
  background: transparent;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 6px 22px;
  color: var(--text);
  background: none;
  -webkit-text-fill-color: currentColor;
  font-family:
    "Aileron",
    "Inter",
    ui-sans-serif,
    system-ui,
    sans-serif;
  font-size: 20px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: 0.08em;
}

.brand::before {
  content: "A";
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  font-size: 16px;
  letter-spacing: 0;
}

.brand::after {
  display: none;
}

.sidebar-menu,
.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.side-group {
  padding: 4px 0;
}

.side-group + .side-group {
  border-top: 1px solid rgba(42, 42, 42, 0.07);
}

.side-group-trigger {
  min-height: 42px;
  padding: 0 10px;
  border-radius: var(--radius-sm);
  color: #374151;
  border: 1px solid transparent;
  background: transparent;
  box-shadow: none;
}

.side-group-trigger:hover {
  color: #111111;
  background: #f8f8f8;
}

.side-group.is-open .side-group-trigger {
  color: #111111;
  background: var(--accent-soft);
  border-color: var(--accent-border);
}

.side-title {
  gap: 9px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0;
}

.side-dot {
  width: 8px;
  height: 8px;
  border-radius: 3px;
  background: #cbd5e1;
}

.side-group.is-open .side-dot {
  background: var(--accent);
  box-shadow: none;
}

.side-arrow {
  width: 24px;
  height: 24px;
  color: #6b7280;
  background: transparent;
}

.side-group-trigger:hover .side-arrow,
.side-group.is-open .side-arrow {
  color: var(--accent);
  background: var(--accent-soft);
}

.side-submenu-inner {
  gap: 4px;
  margin-left: 13px;
  padding-left: 12px;
  border-left: 1px solid #e5e7eb;
}

.side-group.is-open .side-submenu-inner {
  padding-top: 6px;
  padding-bottom: 8px;
}

.side-subitem {
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  color: #6b7280;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0;
}

.side-subitem:hover {
  color: #111111;
  background: #f8f8f8;
  transform: none;
}

.side-subitem.is-active {
  color: var(--accent);
  background: var(--accent-soft);
}

.side-subitem.is-active::before {
  left: -13px;
  width: 2px;
  height: 18px;
  background: var(--accent);
  box-shadow: none;
}

.dashboard-header {
  align-items: center;
  gap: 20px;
  margin-bottom: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border);
}

.header-copy {
  max-width: 820px;
}

.title-row {
  gap: 10px;
}

h1,
.panel-header h2,
.detail-heading h2 {
  font-family:
    "Aileron",
    "Inter",
    ui-sans-serif,
    system-ui,
    sans-serif;
}

h1 {
  color: var(--text);
  font-size: clamp(28px, 3vw, 40px);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: 0;
}

.dashboard-header p {
  max-width: 760px;
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0;
}

.status-chip {
  min-height: 28px;
  padding: 5px 10px;
  border-radius: 999px;
  color: var(--accent);
  border-color: var(--accent-border);
  background: var(--accent-soft);
  font-size: 11px;
  font-weight: 700;
}

.status-dot {
  width: 6px;
  height: 6px;
  background: var(--accent);
  box-shadow: none;
}

.header-actions,
.capture-actions,
.detail-actions,
.sheet-actions,
.sku-row-actions {
  gap: 8px;
}

.primary-btn,
.secondary-btn,
.row-action,
.template-box button,
.sku-row-actions button {
  min-height: 36px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0;
  box-shadow: none;
  transition:
    background 0.16s ease,
    border-color 0.16s ease,
    color 0.16s ease,
    transform 0.16s ease,
    box-shadow 0.16s ease;
}

.primary-btn {
  padding: 9px 14px;
  color: #fff;
  background: var(--accent);
  border: 1px solid var(--accent);
}

.primary-btn:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.primary-btn:active {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.secondary-btn,
.row-action,
.sku-row-actions button {
  padding: 9px 13px;
  color: #1f2937;
  background: #fff;
  border: 1px solid var(--border-strong);
}

.secondary-btn:hover,
.row-action:hover,
.sku-row-actions button:hover {
  color: var(--accent);
  background: #fff8f5;
  border-color: var(--accent-border);
}

.template-box button {
  color: var(--accent);
  background: var(--accent-soft);
  border: 1px solid var(--accent-border);
}

.primary-btn:hover,
.secondary-btn:hover,
.row-action:hover {
  transform: translateY(-1px);
}

.primary-btn:focus-visible,
.secondary-btn:focus-visible,
.row-action:focus-visible,
.queue-tab:focus-visible,
.side-group-trigger:focus-visible,
.side-subitem:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid rgba(255, 69, 0, 0.18);
  outline-offset: 2px;
}

.glass-card,
.panel-card,
.summary-breakdown-card,
.activity-summary-card,
.timeline-event-card {
  border: 1px solid var(--border) !important;
  background: var(--card) !important;
  border-radius: var(--radius-lg) !important;
  box-shadow: var(--shadow-soft) !important;
  backdrop-filter: none !important;
}

.panel-card {
  padding: 20px;
}

.two-column-grid {
  gap: 20px;
  margin-bottom: 20px;
}

.recovery-page {
  gap: 20px;
}

.panel-header,
.detail-heading {
  gap: 14px;
  padding-bottom: 14px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--border);
}

.panel-header h2,
.detail-heading h2 {
  color: var(--text) !important;
  font-size: clamp(18px, 1.5vw, 23px);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: 0;
}

.panel-header p,
.detail-heading p {
  color: var(--muted) !important;
  font-size: 12px;
  font-weight: 500;
}

.recovery-kpi-grid,
.kpi-grid {
  gap: 14px;
}

.kpi-card,
.recovery-kpi-card {
  min-height: 118px;
  padding: 16px;
  overflow: hidden;
}

.kpi-card::before {
  right: -48px;
  bottom: -64px;
  width: 136px;
  height: 136px;
  filter: blur(18px);
  opacity: 0.08;
}

.kpi-top {
  margin-bottom: 12px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.kpi-main {
  margin-bottom: 10px;
}

.kpi-main strong {
  color: var(--accent) !important;
  font-size: clamp(28px, 3vw, 38px);
  font-weight: 800;
  letter-spacing: 0;
}

.kpi-caption {
  padding: 4px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}

.badge,
.pill,
