/* Premium light UI refinement */
:root {
  --altynx-orange: #f45a1e;
  --altynx-orange-light: #ff6a35;
  --altynx-orange-dark: #cf4314;
  --bg: #f7f7f5;
  --sidebar-bg: #ffffff;
  --card: #ffffff;
  --card-soft: #fafafa;
  --surface-raised: #ffffff;
  --surface-subtle: #f4f4f2;
  --border: #e8e8e5;
  --border-strong: #d9d9d5;
  --text: #111111;
  --muted: #5f6368;
  --muted-soft: #8a8f98;
  --accent: var(--altynx-orange);
  --accent-hover: var(--altynx-orange-light);
  --accent-strong: var(--altynx-orange-dark);
  --accent-soft: rgba(244, 90, 30, 0.08);
  --accent-border: rgba(244, 90, 30, 0.22);
  --shadow-soft: 0 1px 2px rgba(17, 17, 17, 0.04), 0 10px 26px rgba(17, 17, 17, 0.05);
  --shadow-tiny: 0 1px 2px rgba(17, 17, 17, 0.035);
  --cyan: var(--accent);
  --blue: var(--accent);
  --purple: #6f737b;
  --rose: #d92d20;
  --amber: #d97706;
  --emerald: #087f5b;
}

html,
body {
  background: var(--bg) !important;
  color: var(--text) !important;
  font-family:
    "Inter",
    "Geist",
    "Manrope",
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Arial,
    sans-serif !important;
  line-height: 1.5;
}

.app-shell {
  background: var(--bg);
}

.sidebar {
  background: var(--sidebar-bg) !important;
  border-right: 1px solid var(--border);
  box-shadow: none;
}

.brand {
  height: 42px;
  margin: 0 8px 24px;
  padding: 0;
  color: var(--text);
}

.brand::before,
.brand::after {
  display: none !important;
  content: none !important;
}

.brand-logo {
  display: block;
  width: 132px;
  max-width: 100%;
  height: auto;
  object-fit: contain;
}

.side-group + .side-group {
  border-top-color: var(--border);
}

.side-group-trigger {
  min-height: 40px;
  border-radius: var(--radius-sm);
  color: #4b5563;
  font-weight: 700;
}

.side-group-trigger:hover {
  color: var(--text);
  background: #f4f4f2;
}

.side-group.is-open .side-group-trigger {
  color: #ffffff;
  background: var(--accent);
  border-color: var(--accent);
  box-shadow: 0 8px 18px rgba(244, 90, 30, 0.14);
}

.side-title {
  font-size: 13px;
  font-weight: 750;
}

.side-dot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: #cbd5e1;
}

.side-group.is-open .side-dot {
  background: #ffffff;
}

.side-arrow {
  color: #8a8f98;
}

.side-group-trigger:hover .side-arrow {
  color: var(--accent);
  background: var(--accent-soft);
}

.side-group.is-open .side-arrow {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.16);
}

.side-submenu-inner {
  border-left-color: var(--border);
}

.side-subitem {
  color: #6b7280;
  font-size: 12px;
  font-weight: 650;
}

.side-subitem:hover {
  color: var(--text);
  background: #f5f5f3;
}

.side-subitem.is-active {
  color: var(--text);
  background: var(--accent-soft);
  font-weight: 750;
}

.side-subitem.is-active::before {
  background: var(--accent);
}

.content {
  background: transparent;
}

.dashboard-header {
  border-bottom-color: var(--border);
}

h1,
.panel-header h2,
.detail-heading h2 {
  font-family:
    "Inter",
    "Geist",
    "Manrope",
    ui-sans-serif,
    system-ui,
    sans-serif;
}

h1 {
  color: var(--text) !important;
  font-size: clamp(30px, 3vw, 42px);
  font-weight: 850;
  letter-spacing: -0.01em;
}

.dashboard-header p,
.panel-header p,
.detail-heading p,
.content :where(p, small) {
  color: var(--muted) !important;
}

.status-chip {
  color: var(--accent);
  border-color: var(--accent-border);
  background: var(--accent-soft);
}

.primary-btn {
  color: #ffffff;
  background: var(--accent);
  border-color: var(--accent);
  box-shadow: 0 8px 18px rgba(244, 90, 30, 0.14);
}

.primary-btn:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
  box-shadow: 0 10px 20px rgba(244, 90, 30, 0.16);
}

.primary-btn:active {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.secondary-btn,
.row-action,
