@keyframes commandQuickFixFillLoop {
  0% {
    transform: scaleX(0);
    transform-origin: left center;
    opacity: 0.78;
  }

  45% {
    transform: scaleX(1);
    transform-origin: left center;
    opacity: 1;
  }

  58% {
    transform: scaleX(1);
    transform-origin: left center;
    opacity: 1;
  }

  100% {
    transform: scaleX(0);
    transform-origin: left center;
    opacity: 0.82;
  }
