/* Keyframes */
@keyframes cqfLineDraw {
  0% {
    stroke-dashoffset: 420;
    opacity: 0.55;
  }

  48% {
    stroke-dashoffset: 0;
    opacity: 1;
  }

  70% {
    stroke-dashoffset: 0;
    opacity: 1;
  }

  100% {
    stroke-dashoffset: -420;
    opacity: 0.65;
  }
}

@keyframes cqfAreaFade {
  0% {
    opacity: 0;
    transform: translateY(6px);
  }

  45% {
    opacity: 1;
    transform: translateY(0);
  }

  72% {
    opacity: 1;
    transform: translateY(0);
  }

  100% {
    opacity: 0.15;
    transform: translateY(4px);
  }
}

@keyframes cqfPointPulse {
  0%,
  20% {
    transform: scale(0.72);
    opacity: 0;
  }

  38% {
    transform: scale(1);
    opacity: 1;
  }

  64% {
    transform: scale(1.18);
    opacity: 1;
  }

  100% {
    transform: scale(0.82);
    opacity: 0.3;
  }
}

@keyframes cqfGraphSweep {
  0% {
    transform: translateX(-120%);
    opacity: 0;
  }

  35% {
    opacity: 1;
  }

  70% {
    transform: translateX(120%);
    opacity: 0.75;
  }

  100% {
    transform: translateX(120%);
    opacity: 0;
  }
}

@keyframes cqfGraphCardSweep {
  0% {
    transform: translateX(-140%);
    opacity: 0;
  }

  38% {
