/* =========================================================
   UNIFIED FILTER BARS — Capture, Product Intelligence, Buyers only
   Mirrors Revenue Pipeline filter chip style without touching KPI/cards
   ========================================================= */

.unified-filter-bar {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin: 0 0 18px;
  padding: 14px 16px;
  border: 1px solid #eadfd4;
  border-radius: 22px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.95), rgba(255, 250, 247, 0.9));
  box-shadow: none;
  overflow: visible;
}

.unified-filter-chip-list {
  min-width: 0;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  overflow: visible;
}

.unified-filter-chip {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 13px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: #f2f1ef;
  color: #3f3f46;
  font-size: 13px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: -0.015em;
  white-space: nowrap;
  cursor: pointer;
  box-shadow: none;
  transition:
    background 0.16s ease,
    border-color 0.16s ease,
    color 0.16s ease,
    transform 0.16s ease;
}

.unified-filter-chip:hover {
  transform: translateY(-1px);
  border-color: #eadfd4;
  background: #ffffff;
  color: #111111;
}

.unified-filter-chip.is-active {
  color: #c2410c;
  border-color: rgba(255, 69, 0, 0.55);
  background: #fff7ed;
  box-shadow: inset 0 0 0 1px rgba(255, 69, 0, 0.06);
}

.unified-filter-icon {
  width: 15px;
  height: 15px;
  flex: 0 0 15px;
  color: #6b7280;
  filter: none;
  box-shadow: none;
}

.unified-filter-chip.is-active .unified-filter-icon {
  color: #ff4500;
}

.unified-filter-count {
  min-width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
